import React, { useState, useEffect } from 'react';
import axios from 'axios';

const StudentManagement = () => {
  const [students, setStudents] = useState([]);
  const [formData, setFormData] = useState({
    studentId: '',
    name: '',
    email: '',
    phone: '',
    studentClass: ''
  });

  const { studentId, name, email, phone, studentClass } = formData;

  useEffect(() => {
    fetchStudents();
  }, []);

  const fetchStudents = async () => {
    try {
      const token = localStorage.getItem('token');
      const res = await axios.get('http://localhost:5000/api/students', {
        headers: {
          'x-auth-token': token
        }
      });
      setStudents(res.data);
    } catch (err) {
      console.error(err);
      alert('Could not fetch students. Please log in again.');
    }
  };

  const onChange = e => setFormData({ ...formData, [e.target.name]: e.target.value });

  const onSubmit = async e => {
    e.preventDefault();
    try {
      const token = localStorage.getItem('token');
      await axios.post('http://localhost:5000/api/students', {
        ...formData
      }, {
        headers: {
          'x-auth-token': token
        }
      });
      fetchStudents(); // Refresh the list after adding a new student
      setFormData({ studentId: '', name: '', email: '', phone: '', studentClass: '' }); // Clear the form
    } catch (err) {
      console.error(err.response.data);
      alert('Failed to add student. Check the console for details.');
    }
  };

  return (
    <div>
      <h2>Student Management</h2>
      <form onSubmit={onSubmit}>
        <input type="text" name="studentId" value={studentId} onChange={onChange} placeholder="Student ID" required />
        <input type="text" name="name" value={name} onChange={onChange} placeholder="Name" required />
        <input type="email" name="email" value={email} onChange={onChange} placeholder="Email" required />
        <input type="text" name="phone" value={phone} onChange={onChange} placeholder="Phone" />
        <input type="text" name="studentClass" value={studentClass} onChange={onChange} placeholder="Class" required />
        <button type="submit">Add Student</button>
      </form>

      <h3>Student List</h3>
      <table>
        <thead>
          <tr>
            <th>Student ID</th>
            <th>Name</th>
            <th>Email</th>
            <th>Phone</th>
            <th>Class</th>
          </tr>
        </thead>
        <tbody>
          {students.map(student => (
            <tr key={student._id}>
              <td>{student.studentId}</td>
              <td>{student.name}</td>
              <td>{student.email}</td>
              <td>{student.phone}</td>
              <td>{student.class}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default StudentManagement;
